payroll_contract_notes = {
    ("Brooklyn Nets", "Moritz Wagner"): (
        "2-year, $18.45M contract: $9M in 2026-27; $9.45M in 2027-28 (mutual option)."
    ),
    ("Detroit Pistons", "Jalen Duren"): (
        "2026-27 base salary: $34,482,759. His five-year, $200M extension averages $40M per year; actual future-year salaries vary."
    ),
}

for team in teams:
    team_payroll = payroll_2026_27.get(team["name"], {})
    roster = team["starters_2026_27"] + team["bench_2026_27"]
    players_by_name = {player["name"].casefold(): player for player in roster}

    for player_name, salary in team_payroll.items():
        player = players_by_name.get(player_name.casefold())
        if player is None:
            player = {
                "name": player_name,
                "pos": "F",
                "pts": 0.0,
                "reb": 0.0,
                "ast": 0.0,
                "stl": 0.0,
                "blk": 0.0,
                "tov": 0.0,
                "fg": 0.0,
                "fg3": 0.0,
                "ft": 0.0,
                "salary": salary,
            }
            team["bench_2026_27"].append(player)
            players_by_name[player_name.casefold()] = player
        else:
            player["salary"] = salary
        contract_note = payroll_contract_notes.get((team["name"], player_name))
        if contract_note:
            player["contract_note"] = contract_note
            if player_name == "Moritz Wagner":
                player["contract_label"] = "2027-28 mutual option"

# ==============================================================================
# API KEY AUTHENTICATION
# ==============================================================================
def verify_api_key(x_api_key: Optional[str] = Header(default=None)):
    if x_api_key != API_KEY:
        raise HTTPException(
            status_code=401,
            detail="Invalid or missing API key."
        )
    return True

# ==============================================================================
# ROUTE ENDPOINTS
# ==============================================================================
@app.get("/health")
def health_check():
    return {
        "status": "ok",
        "service": "NBA Hub API",
        "version": API_VERSION,
        "timestamp": datetime.utcnow().isoformat() + "Z"
    }

@app.get("/api/v1/teams/search", dependencies=[Depends(verify_api_key)])
def search_teams(q: str = Query(..., min_length=1)):
    query = q.lower()
    results = []
    for team in teams:
        starter_names = " ".join([p["name"] for p in team.get("starters_2026_27", [])])
        bench_names = " ".join([p["name"] for p in team.get("bench_2026_27", [])])
        searchable_text = (
            f"{team['name']} {team['conference']} {team['division']} "
            f"{team['featured_star']} {team['tax_status']} {team['last_season_record']} "
            f"{starter_names} {bench_names} {team['description']}"
        ).lower()
        if query in searchable_text:
            results.append(team)

    return {
        "query": q,
        "count": len(results),
        "results": results
    }

@app.get("/api/v1/teams", dependencies=[Depends(verify_api_key)])
def get_teams():
    return {
        "count": len(teams),
        "teams": teams
    }

@app.get("/api/v1/teams/{team_id}", dependencies=[Depends(verify_api_key)])
def get_team(team_id: int):
    for team in teams:
        if team["id"] == team_id:
            return team
    raise HTTPException(status_code=404, detail="Team not found.")

@app.get("/teams")
def get_teams_legacy():
    return {"teams": teams}

@app.get("/api/v1/health")
def health_check_v1():
    return health_check()
